const fs = require('fs');
const path = require('path');

const {generateKmsCaroots} = require('./index');

const outputPath = path.join(__dirname, 'caroots.js');

generateKmsCaroots()
  .then((caroots) => {
    const output = `/*!
 * Copyright (c) 2026 Cisco Systems, Inc. See LICENSE file.
 */

// Generated by generate-bundle.js. Do not edit.
module.exports = ${JSON.stringify(caroots)};
`;

    fs.writeFileSync(outputPath, output);
    console.log(`Wrote ${caroots.length} CA roots to ${outputPath}`);
  })
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });